INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PNDT2100000000000000000A', '*', '', 'pn_doc21_pickup_card', 'Carte de personne autorisée à récupérer l’enfant (maternelle publique)', 'other', 'K', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["section_label","person_name","relationship","grant_label"]', '2026-11-05T15:01:00+01:00', '2026-11-05T15:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PNDT21F00000000000000000', '*', '', 'pn_doc21_pickup_card', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Carte de personne autorisée</h2><p><strong>{{person_name}}</strong> ({{relationship}}) est autorisé(e) à récupérer <strong>{{holder_name}}</strong>, section {{section_label}}. Validité : {{grant_label}}.</p><p>La carte ne suffit pas : l’agent vérifie la personne, la liste du jour et, le cas échéant, le code du jour. Elle est révoquée avec l’autorisation.</p><p>Fait le {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Numéro : {{number}}</p><div>{{qr}}</div><p>Vérification : {{verification_url}}</p></body></html>', 1, '2026-11-05T15:01:00+01:00', NULL, '2026-11-05T15:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PNDT21E00000000000000000', '*', '', 'pn_doc21_pickup_card', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Authorised pick-up card</h2><p><strong>{{person_name}}</strong> ({{relationship}}) is authorised to pick up <strong>{{holder_name}}</strong>, section {{section_label}}. Validity: {{grant_label}}.</p><p>The card is not enough: staff check the person, the list of the day and, where relevant, the daily code. It is revoked with the authorisation.</p><p>Issued on {{issued_on}}.</p><div>{{signature}}{{stamp}}</div><p>Number: {{number}}</p><div>{{qr}}</div><p>Verification: {{verification_url}}</p></body></html>', 1, '2026-11-05T15:01:00+01:00', NULL, '2026-11-05T15:01:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PNDT1900000000000000000A', '*', '', 'pn_doc19_register', 'Registre des arrivées et sorties du jour (maternelle publique)', 'other', 'R', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["register_date","totals_text","rows_text"]', '2026-11-05T15:01:00+01:00', '2026-11-05T15:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PNDT19F00000000000000000', '*', '', 'pn_doc19_register', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Registre des arrivées et sorties du {{register_date}}</h2><p>{{totals_text}}</p><p style="white-space:pre-line">{{rows_text}}</p><p>Édité le {{issued_on}} par {{holder_name}}. Numéro : {{number}}</p></body></html>', 1, '2026-11-05T15:01:00+01:00', NULL, '2026-11-05T15:01:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PNDT19E00000000000000000', '*', '', 'pn_doc19_register', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Arrival and departure register of {{register_date}}</h2><p>{{totals_text}}</p><p style="white-space:pre-line">{{rows_text}}</p><p>Printed on {{issued_on}} by {{holder_name}}. Number: {{number}}</p></body></html>', 1, '2026-11-05T15:01:00+01:00', NULL, '2026-11-05T15:01:00+01:00')
